def max_tandem_repeat(s, k):
    n = len(s)
    max_length = 0

    for length in range(2, n + k + 1, 2):
        if length > n:
            suffix = s[-(length - n):]
        else:
            suffix = s[-length:]

        if suffix == suffix[::-1] and suffix[:length // 2] == suffix[length // 2:]:
            max_length = length

    return max_length

